<?php $page = $modulePageData; $isFlow = in_array($page['view'], ['movements', 'incoming', 'outgoing'], true); $isSold = in_array($page['view'], ['sold', 'purchased'], true); $isPurchase = $page['view'] === 'purchased'; ?>
<?php if ($page['errors']): ?><div class="notice notice-error" role="alert"><?php foreach ($page['errors'] as $error): ?><p><?= inventoryEscape($error) ?></p><?php endforeach; ?></div><?php endif; ?>
<?php if ($page['available']): ?>
<section aria-labelledby="report-title">
    <div class="contact-toolbar"><div><?php if ($page['productId']): ?><a class="overview-link" href="index.php?id=<?= $page['productId'] ?>">← Volver al producto</a><?php endif; ?><p class="eyebrow">INVENTARIO · INFORMES</p><h1 id="report-title"><?= inventoryEscape($page['title']) ?></h1><p class="section-subtitle"><?= $page['total'] ?> registros · <?= inventoryEscape(match ($page['view']) { 'movements' => 'Operaciones realizadas', 'incoming', 'outgoing' => 'Movimientos realizados · últimos 12 meses', 'sold' => 'Órdenes de venta confirmadas · últimos 365 días', 'purchased' => 'Órdenes de compra confirmadas', default => 'Cantidades actuales' }) ?></p></div><?php if ($page['view'] === 'stock'): ?><a class="contact-button" href="informes.php?view=movements<?= $page['productId'] ? '&amp;product_id=' . $page['productId'] : '' ?>">Historial de movimientos</a><?php endif; ?></div>
    <form class="contact-filters" method="get" action="informes.php"><input type="hidden" name="view" value="<?= $page['view'] ?>">
        <?php if ($isSold): ?><label>Vista<select name="display"><?php foreach (['list' => 'Lista', 'pivot' => 'Tabla dinámica', 'graph' => 'Gráfico'] as $value => $label): ?><option value="<?= $value ?>" <?= $page['display'] === $value ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>Agrupar por<select name="group"><?php foreach (['month' => 'Fecha de la orden · mes', 'contact' => $isPurchase ? 'Proveedor' : 'Cliente', 'none' => 'Sin agrupar'] as $value => $label): ?><option value="<?= $value ?>" <?= $page['group'] === $value ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select></label><?php endif; ?>
        <label>Buscar<input type="search" name="q" maxlength="160" value="<?= inventoryEscape($page['search']) ?>" placeholder="<?= $page['view'] === 'movements' ? 'Producto, referencia o contacto' : 'Producto' ?>"></label>
        <label>Producto<select name="product_id"><option value="">Todos los productos</option><?php foreach ($page['products'] as $product): ?><option value="<?= (int) $product['id'] ?>" <?= $page['productId'] === (int) $product['id'] ? 'selected' : '' ?>><?= inventoryEscape($product['name']) ?></option><?php endforeach; ?></select></label>
        <?php if (! $isSold): ?><label>Ubicación<select name="location_id"><option value="">Todas las ubicaciones</option><?php foreach ($page['storage']['locations'] as $location): ?><option value="<?= (int) $location['id'] ?>" <?= $page['locationId'] === (int) $location['id'] ? 'selected' : '' ?>><?= inventoryEscape(storageLabel($page['storage'], (int) $location['warehouse_id'], (int) $location['id'])) ?></option><?php endforeach; ?></select></label><?php endif; ?>
        <button class="contact-button" type="submit">Filtrar</button><a class="contact-button" href="informes.php?view=<?= $page['view'] ?>">Limpiar</a>
    </form>
    <?php if ($isSold && $page['display'] === 'pivot'): ?>
        <div class="contact-table-wrap"><table class="contact-table"><thead><tr><th scope="col"><?= $page['group'] === 'contact' ? ($isPurchase ? 'Proveedor' : 'Cliente') : 'Mes' ?></th><th scope="col">Cantidad</th><th scope="col">Importe sin impuestos</th></tr></thead><tbody>
            <?php $quantityTotal = '0.000'; $amountTotal = '0.00'; foreach ($page['summary'] as $summary): ?><?php $quantityTotal = bcadd($quantityTotal, $summary['quantity'], 3); $amountTotal = bcadd($amountTotal, $summary['subtotal'], 2); ?><tr><td><?= inventoryEscape($summary['label']) ?></td><td><?= inventoryEscape($summary['quantity']) ?></td><td><?= inventoryEscape(bcadd($summary['subtotal'], '0', 2)) ?></td></tr><?php endforeach; ?>
        </tbody><tfoot><tr><th scope="row">Total</th><td><?= inventoryEscape($quantityTotal) ?></td><td><?= inventoryEscape($amountTotal) ?></td></tr></tfoot></table></div>
    <?php elseif ($isSold && $page['display'] === 'graph'): ?>
        <div class="report-graph" aria-label="Cantidades por <?= $page['group'] === 'contact' ? 'contacto' : 'mes' ?>">
            <?php $maxQuantity = max(1, ...array_map(static fn ($row) => (float) $row['quantity'], $page['summary'])); foreach ($page['summary'] as $summary): ?><div class="report-graph-row"><span><?= inventoryEscape($summary['label']) ?></span><div class="report-graph-bar" style="width: <?= max(1, min(100, (float) $summary['quantity'] * 100 / $maxQuantity)) ?>%" aria-hidden="true"></div><strong><?= inventoryEscape($summary['quantity']) ?></strong></div><?php endforeach; ?>
            <?php if (! $page['summary']): ?><p class="section-subtitle">No hay órdenes confirmadas que coincidan con los filtros.</p><?php endif; ?>
        </div>
    <?php else: ?>
    <div class="contact-table-wrap" role="region" aria-label="<?= inventoryEscape($page['title']) ?>" tabindex="0"><table class="contact-table"><thead><tr>
        <?php if ($isFlow || $isSold): ?><th scope="col"><?= $page['view'] === 'movements' ? 'Fecha del movimiento' : 'Fecha' ?></th><th scope="col">Referencia</th><?php endif; ?>
        <th scope="col">Producto</th><?php if ($isFlow): ?><th scope="col">Origen</th><th scope="col">Destino</th><?php elseif ($isSold): ?><th scope="col"><?= $isPurchase ? 'Proveedor' : 'Cliente' ?></th><?php else: ?><th scope="col">Ubicación / almacén</th><?php endif; ?><th scope="col"><?= inventoryEscape(match ($page['view']) { 'movements' => 'Cantidad movida', 'incoming', 'outgoing' => 'Cantidad movida', 'sold' => 'Cantidad vendida', 'purchased' => 'Cantidad comprada', default => 'Cantidad a la mano' }) ?></th><?php if ($isSold): ?><th scope="col">Importe sin impuestos</th><?php endif; ?>
    </tr></thead><tbody>
        <?php $previousGroup = null; $groupNumber = 0; foreach ($page['rows'] as $row): ?>
            <?php if ($isSold && $page['group'] !== 'none'): ?><?php $groupKey = $page['group'] === 'contact' ? (string) $row['contact_id'] : substr($row['moved_at'], 0, 7); ?>
                <?php if ($groupKey !== $previousGroup): ?><?php $previousGroup = $groupKey; $groupNumber++; $groupTotal = ['quantity' => '0.000', 'subtotal' => '0.00']; foreach ($page['summary'] as $summary) { if ((string) $summary['group_key'] === $groupKey) { $groupTotal = $summary; break; } } ?><tr class="report-group-heading"><td colspan="4"><button type="button" data-report-group-toggle="group-<?= $groupNumber ?>" aria-expanded="true"><?= inventoryEscape($page['group'] === 'contact' ? $row['contact_name'] : $groupKey) ?></button></td><td><?= inventoryEscape($groupTotal['quantity']) ?></td><td><?= inventoryEscape(bcadd($groupTotal['subtotal'], '0', 2)) ?></td></tr><?php endif; ?>
            <?php endif; ?>
            <tr <?= $isSold && $page['group'] !== 'none' ? 'data-report-group="group-' . $groupNumber . '"' : '' ?>>
            <?php if ($isFlow || $isSold): ?><td><?= inventoryEscape($row['moved_at']) ?></td><td><a class="contact-name" href="<?= $isSold ? ($isPurchase ? '../compras/orden.php?id=' : '../ventas/index.php?id=') . (int) $row['operation_id'] : 'operaciones.php?type=' . inventoryEscape($row['operation_type']) . '&amp;id=' . (int) $row['operation_id'] ?>"><?= inventoryEscape($row['reference']) ?></a></td><?php endif; ?>
            <td><a class="contact-name" href="index.php?id=<?= (int) $row['product_id'] ?>"><?= inventoryEscape($row['product_name']) ?></a></td>
            <?php if ($isFlow): ?>
                <td><?= inventoryEscape($row['operation_type'] === 'receipt' ? (storageLabel($page['storage'], null, inventoryId($row['source_location_id'])) ?: 'Proveedores') . ' · ' . ($row['contact_name'] ?? '') : storageLabel($page['storage'], inventoryId($row['source_warehouse_id']), inventoryId($row['source_location_id']))) ?></td>
                <td><?= inventoryEscape($row['operation_type'] === 'delivery' ? (storageLabel($page['storage'], null, inventoryId($row['destination_location_id'])) ?: 'Clientes') . ' · ' . ($row['contact_name'] ?? '') : storageLabel($page['storage'], inventoryId($row['destination_warehouse_id']), inventoryId($row['destination_location_id']))) ?></td>
            <?php elseif ($isSold): ?><td><?= inventoryEscape($row['contact_name']) ?></td><?php else: ?><?php $location = storageRecord($page['storage']['locations'], (int) $row['location_id']); ?><td><a class="contact-name" href="informes.php?view=movements&amp;product_id=<?= (int) $row['product_id'] ?>&amp;location_id=<?= (int) $row['location_id'] ?>"><?= inventoryEscape(storageLabel($page['storage'], $location ? (int) $location['warehouse_id'] : null, (int) $row['location_id'])) ?></a></td><?php endif; ?>
            <td><?= inventoryEscape($row['quantity']) ?></td>
            <?php if ($isSold): ?><td><?= inventoryEscape(bcadd($row['subtotal'], '0', 2)) ?></td><?php endif; ?>
        </tr><?php endforeach; ?>
        <?php if (! $page['rows']): ?><tr><td colspan="<?= $isFlow || $isSold ? 6 : 3 ?>" class="contact-empty"><?= $isPurchase ? 'No hay órdenes de compra confirmadas para este producto. Las recepciones manuales se consultan en el historial de movimientos.' : 'No hay registros que coincidan con los filtros.' ?></td></tr><?php endif; ?>
    </tbody></table></div>
    <?php endif; ?>
    <?php if (! $isSold || $page['display'] === 'list'): ?><nav class="contact-pagination" aria-label="Páginas del informe"><span>Página <?= $page['currentPage'] ?> de <?= $page['pages'] ?></span><?php foreach (['Anterior' => $page['currentPage'] - 1, 'Siguiente' => $page['currentPage'] + 1] as $label => $number): ?><?php if ($number >= 1 && $number <= $page['pages']): ?><a class="contact-button" href="informes.php?<?= inventoryEscape(http_build_query(['view' => $page['view'], 'q' => $page['search'], 'product_id' => $page['productId'], 'location_id' => $page['locationId'], 'display' => $page['display'], 'group' => $page['group'], 'page' => $number])) ?>"><?= $label ?></a><?php endif; ?><?php endforeach; ?></nav><?php endif; ?>
</section>
<?php endif; ?>
